-- Mod-authored era splash painting descriptions, es_ES overlay.
-- Baseline in CivVAccess_EraDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_MISSING"] = "No hay descripción para esta era."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_CLASSICAL"] =
    "Un gran templo con columnas se alza en lo alto de una colina aterrazada; salas con columnata más pequeñas descienden escalonadas a su derecha. Jardines suben por la ladera por debajo de ellas, donde estrechas escalinatas serpentean junto a un saliente de roca pálida cubierto de cipreses y arbustos en flor. Todo el mármol resplandece dorado y cálido bajo el sol."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MEDIEVAL"] =
    "Dorados campos de trigo se extienden al pie de una ciudad amurallada de pálidas torres sobre una colina. Estandartes rojos cuelgan de sus almenas; el mayor lleva un ave negra con las alas desplegadas. Es tiempo de cosecha: campesinos encorvados recogen el grano segado, otros cargan altos haces a la espalda, y unos trabajadores en el centro cargan un carro uncido a una yunta de bueyes oscuros. Los árboles se cierran en las esquinas superiores bajo un suave cielo de calima."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_RENAISSANCE"] =
    "Por encima de los tejados de Florencia, Miguel Ángel está de pie en una escalera de madera, tallando el colosal David de mármol blanco. La cabeza y los hombros de la estatua solos llenan la izquierda del encuadre; el escultor apenas alcanza el hombro. Abajo, los tejados de tejas rojas se alejan hasta la gran cúpula de la Catedral de Florencia y un esbelto campanario. Detrás de ellos, la luz dorada rompe a través del cielo oscurecido por la tormenta."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_INDUSTRIAL"] =
    "Un vapor de paletas rojo y blanco cruza el puerto de Nueva York en primer plano, dejando una estela de humo de dos chimeneas negras. Los pasajeros se alinean en sus dobles cubiertas. Detrás de él, la Estatua de la Libertad se alza verde contra un cielo de ámbar bruñoso; más barcos navegan a vapor por el agua más allá. El humo y la bruma tiñen toda la escena de cálido sepia y dorado."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MODERN"] =
    "El espectador mira desde la azotea de un rascacielos hacia una ciudad llena de ellos. Torres iluminadas se alejan manzana tras manzana en una bruma dorada. Muy abajo, autopistas elevadas serpentean por un gran intercambiador donde coches y camiones circulan por las curvas. Toda la pintura es de un solo color, dorado y sepia como una fotografía teñida."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_POSTMODERN"] =
    "Un sol bajo arde al fondo de una calle del centro de mediados del siglo XX, inundándola de luz dorada. Hombres con traje y sombrero fedora caminan por la acera de la derecha de espaldas al espectador, junto a toldos y una gran marquesina de letras. Sedanes oscuros y redondeados aparcan junto al bordillo o pasan rodando. Al fondo, los edificios se disuelven en el resplandor."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_FUTURE"] =
    "Una ciudad futurista brilla a lo largo de una costa dorada, sus esbeltas torres alejándose por la orilla entre la bruma. A la izquierda, un esbelto avión a reacción rojo y blanco vira sobre el agua; detrás de él, un puente colgante cruza la bahía. En el primer plano derecho, un complejo de cromo y cristal coronado por una cúpula está construido en los propios acantilados costeros. Vegetación recorre sus terrazas; una figura solitaria está de pie en una pasarela."